{"script":"() => {
  const links = Array.from(document.querySelectorAll('a[data-testid="internal-link"]'));
  const result = links.map(link => ({
    href: link.href,
    headline: link.querySelector('h2')?.textContent || '',
    text: link.textContent.substring(0, 100)
  })).filter(l => l.headline.includes('Bronze Age') || l.headline.includes('Archaeolog'));
  return result;
}"}

